                free.append((i, 0))
                free.append((i, 1))
        for v in range(spine, n):
            k = rng.randrange(len(free))
            free[k], free[-1] = free[-1], free[k]
            u, s = free.pop()
            if s == 0:
                L[u] = v
            else:
                R[u] = v
            free.append((v, 0))
            free.append((v, 1))
        vals = [rng.randint(-1000, 1000) for _ in range(n)]
